const tests = [
 '=SUMPRODUCT((book2!A:A=A3)*book2!H:J)',
 '=SUMPRODUCT((book2!$A:$A=$A3)*book2!$H:$J)',
 "=SUMPRODUCT(('book2'!A:A='book1'!A3)*'book2'!H:J)",
 '=SUMPRODUCT((book2!A:A=book1!$A$3)*book2!H:J)',
 '=SUMPRODUCT((book2!$A$1:$A$22=book1!A3)*book2!$H$1:$J$22)',
 '=SUMPRODUCT((book2!$A$1:$A$22=A3)*book2!$H$1:$J$22)',
];
const s = wb.getWorksheet('book1');
const c = s.getRange('D1');
const out=[];
for (const t of tests){ c.setValue(t); out.push(t+' -> '+c.getCell().getValue?.()+' / '+c.getText?.()); }
c.clear();
out

